                    _ = try writer.write(Output.prettyFmt("<r><d>[fetch]<r> ", true));
                }
                _ = try writer.write("< ");
                _ = try writer.print("{f}\n", .{ header });
            }
    }

pub fn count(self: Response, builder: *StringBuilder) void {
            _ = builder.count(self.status);
            for (cp_iter_slice(self.headers.list)) |header| {
                _ = &header;
                _ = header.count(builder);
            }
    }

pub fn clone(self: Response, out_headers: []Header, builder: *StringBuilder) Response {
            var i: usize = 0;
            _ = &i;
            while ((i < self.headers.list.len)) : (i = (i + 1)) {
                out_headers[cp_cast_int(usize, i)] = self.headers.list[@as(usize, @intCast(i))].clone(builder);
            }
            return Response{ .minor_version = self.minor_version, .status_code = self.status_code, .status = builder.append(self.status), .headers = HeaderList{ .list = out_headers[0..self.headers.list.len] }, .bytes_read = self.bytes_read };
    }

pub fn parseParts(buf: []const u8, src: []Header, offset: ?*usize) !Response {
            var minor_version: c_int = 1;
            _ = &minor_version;
            var status_code: c_int = 0;
            _ = &status_code;
            var status: []const u8 = "";
            _ = &status;
            var num_headers: usize = src.len;
            _ = &num_headers;
            var rc: c_int = 0;
            _ = &rc;
            {
                var off_ptr: *usize = @as(*usize, @ptrCast(@alignCast(offset.?)));
                _ = &off_ptr;
                rc = c.phr_parse_response(buf.ptr, buf.len, @as(*c_int, @ptrCast(@alignCast(&(minor_version)))), @as(*c_int, @ptrCast(@alignCast(&(status_code)))), @as([*c][*c]const u8, @ptrCast(@alignCast(&(status.ptr)))), @as(*usize, @ptrCast(@alignCast(&(status.len)))), @as(*c.phr_header, @ptrCast(@alignCast(src.ptr))), @as(*usize, @ptrCast(@alignCast(&(num_headers)))), off_ptr.*);
                if ((rc == -2)) {
                    off_ptr.* = (off_ptr.* + buf.len);
                }
            }
            if ((rc == -1)) {
                if (comptime Environment.allow_assert) {
                    _ = Output.debug("Malformed HTTP response:\n{s}", .{ buf });
                    return error.Malformed_HTTP_Response;
                }
                return error.Malformed_HTTP_Response;
            }
            if ((rc == -2)) {
                return error.ShortRead;
            }
            return Response{ .minor_version = (if (comptime @typeInfo(@TypeOf(minor_version)) == .@"enum") cp_cast_int(usize, @intFromEnum(minor_version)) else cp_cast_int(usize, minor_version)), .status_code = (if (comptime @typeInfo(@TypeOf(status_code)) == .@"enum") cp_cast_int(u32, @intFromEnum(status_code)) else cp_cast_int(u32, status_code)), .status = status, .headers = HeaderList{ .list = src[0..@min(num_headers, src.len)] }, .bytes_read = rc };
    }

pub fn parse(buf: []const u8, src: []Header) !Response {
            var offset: usize = 0;
            _ = &offset;
            const response = try parseParts(buf, src, (&offset));
            return response;
    }
};

pub const Headers = struct {
    headers: []const Header,

pub fn format(self: Headers, writer: *std.Io.Writer) !void {
            for (cp_iter_slice(self.headers)) |header| {
                _ = &header;
                _ = try writer.print("{s}: {s}\r\n", .{ header.name, header.value });
            }
    }

pub fn parse(buf: []const u8, src: []Header) !Headers {
            var num_headers: usize = src.len;
            _ = &num_headers;
            var rc: c_int = 0;
            _ = &rc;
            {
                rc = c.phr_parse_headers(buf.ptr, buf.len, @as(*c.phr_header, @ptrCast(@alignCast(src.ptr))), @as([*c]usize, @ptrCast(@alignCast(&(num_headers)))), 0);
            }
            if ((rc == -1)) {
                return error.BadHeaders;
            }
            if ((rc == -2)) {
                return error.ShortRead;
            }
            return Headers{ .headers = src[0..num_headers] };
    }
};

const Environment = bun.Environment;
const Output = bun.Output;
const StringBuilder = bun.StringBuilder;
const assert = bun.assert;
const strings = bun.strings;
var EMPTY_HEADERS: [0]Header = undefined;
pub const phr_header = c.phr_header;
pub const phr_chunked_decoder = c.phr_chunked_decoder;
pub const struct_phr_header = c.struct_phr_header;
pub const struct_phr_chunked_decoder = c.struct_phr_chunked_decoder;
pub const phr_parse_request = c.phr_parse_request;
pub const phr_parse_response = c.phr_parse_response;
pub const phr_parse_headers = c.phr_parse_headers;
pub const phr_decode_chunked = c.phr_decode_chunked;
pub const phr_decode_chunked_is_in_data = c.phr_decode_chunked_is_in_data;
